public class CsvGenerator {
    public static String buildCsv(int count) {
        // Pre-size capacity to prevent buffer resizing
        StringBuilder sb = new StringBuilder(count * 6);
        for (int i = 0; i < count; i++) {
            if (i > 0) sb.append(',');
            sb.append(i);
        }
        return sb.toString(); // O(n) linear execution
    }
}

